WITH lines AS (SELECT id, plan, effective_from, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_limits) x AS tier_value) SELECT DATE_TRUNC('WEEK', effective_from) AS week_start, plan, SIZE(COLLECT_SET(plan)) AS num_plans, COUNT_IF(plan = 'basic') AS basic_events, SUM(tier_value) FILTER (WHERE plan = 'basic') AS basic_total_tier_value, ROUND(AVG(tier_value), 2) AS avg_tier_value, COUNT(*) AS row_count, COUNT(*) FILTER (WHERE plan = 'basic') AS basic_rows FROM lines GROUP BY CUBE (DATE_TRUNC('WEEK', effective_from), plan) HAVING COUNT(*) FILTER (WHERE plan = 'basic') < 1000 ORDER BY basic_events ASC NULLS FIRST;
